:::


With noncyclic group margins, the MSF~sc(diary)~ post-midsleep window remains about 0.9–5.3 hours. The broad opposite cyclic window separates into two pre-midsleep sections, approximately −11.6 to −8.8 hours and −7.8 to −5.3 hours. Thus its precise span depends on the group-curve boundary specification.

Individual-curve and peak-timing calculations are also repeated with the original 1,000 joint coefficient draws. Their [complete timing table](sensitivity/diary-msfsc/comparison/individual_timing.csv), [matched-placement summaries](sensitivity/diary-msfsc/comparison/matched_placement.csv), and each scenario's plots retain the detailed outputs.


::: {.cell}

```{.r .cell-code  code-fold="true" code-summary="Show individual timing, common photoperiod and placement calculations"}
if (stage == "outputs") {
  for (label in c("primary", "chest")) {
    curves <- contrasts <- list()
    for (axis in c("clock", "phase")) {
      bundle <- readRDS(paste0("results/models/", label, "_", axis, ".rds"))
      inference <- readRDS(paste0(
        "results/data/",
        label,
        "_",
        axis,
        "_inference.rds"
      ))
      curves[[axis]] <- mutate(inference$curves, axis = axis)
      contrasts[[axis]] <- mutate(inference$contrasts, axis = axis)
      photoperiod_figure(bundle)
      if (label == "primary") {
        set.seed(cfg$seed + if (axis == "phase") 1L else 0L)
        joint_draws <- as.matrix(gratia::gaussian_draws(
          bundle$fit,
          n = cfg$draws,
          unconditional = covariance_info(bundle$fit)$unconditional
        ))
        inference$individual_draws <- joint_draws[
          seq_len(1000L),
          ,
          drop = FALSE
        ]
        rm(joint_draws)
        individual_curves(bundle, inference)
      }
      rm(bundle, inference)
      gc()
    }
    for (context in c("Overall", "Work", "Free")) {
      save_plot(
        pattern_figure(bind_rows(curves), context, label),
        paste0(label, "_patterns_", tolower(context)),
        12,
        11
      )
      for (family in c("Evening minus morning", "Extreme minus moderate"))
        save_plot(
          difference_figure(bind_rows(contrasts), family, context, label),
          paste0(
            label,
            "_",
            gsub(" ", "_", tolower(family)),
            "_",
            tolower(context)
          ),
          12,
          11
        )
    }
    for (family in c("Free minus work", "Interactions"))
      save_plot(
        difference_figure(bind_rows(contrasts), family, placement = label),
        paste0(label, "_", gsub(" ", "_", tolower(family))),
        12,
        14
      )
  }
  matched_placement_check(prepared)
}
```
